import{_ as t,o as s,c as n,ah as a}from"./chunks/framework.BsNNkeaH.js";const m=JSON.parse('{"title":"Demandes de congé","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/conges.md","filePath":"src/guide/conges.md"}'),r={name:"guide/conges.md"};function o(d,e,i,l,u,p){return s(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="demandes-de-conge" tabindex="-1">Demandes de congé <a class="header-anchor" href="#demandes-de-conge" aria-label="Permalink to &quot;Demandes de congé&quot;">​</a></h1><p>Les congés sont l&#39;une des rares fonctions d&#39;ERA qui ne dépendent pas de votre rôle : <strong>tout membre du personnel</strong> dépose ses propres demandes, qu&#39;il soit enseignant, caissier, infirmier ou responsable d&#39;internat. Seule la décision est réservée à l&#39;administration.</p><h2 id="deposer-une-demande" tabindex="-1">Déposer une demande <a class="header-anchor" href="#deposer-une-demande" aria-label="Permalink to &quot;Déposer une demande&quot;">​</a></h2><p>Depuis <strong>Mes demandes de congé</strong> :</p><ol><li>Renseignez le <strong>type</strong> : congé payé, congé sans solde ou congé maladie.</li><li>Indiquez la <strong>date de début</strong> et la <strong>date de fin</strong>.</li><li>Écrivez le <strong>motif</strong>.</li><li>Cliquez sur <strong>Soumettre la demande</strong>.</li></ol><p>La demande part au statut <strong>En attente</strong>. Vous n&#39;avez rien d&#39;autre à faire : l&#39;administration la voit apparaître dans sa propre file.</p><h2 id="suivre-ses-demandes" tabindex="-1">Suivre ses demandes <a class="header-anchor" href="#suivre-ses-demandes" aria-label="Permalink to &quot;Suivre ses demandes&quot;">​</a></h2><p>La section <strong>Historique</strong> de la même page liste vos demandes passées et en cours, avec leur statut :</p><table tabindex="0"><thead><tr><th>Statut</th><th>Ce qu&#39;il signifie</th></tr></thead><tbody><tr><td>En attente</td><td>Déposée, pas encore examinée</td></tr><tr><td>Approuvée</td><td>Accordée par l&#39;administration</td></tr><tr><td>Rejetée</td><td>Refusée — le motif du rejet est affiché avec la demande</td></tr></tbody></table><p>Vous ne voyez que vos propres demandes, jamais celles de vos collègues.</p><div class="tip custom-block"><p class="custom-block-title">Le dépôt n&#39;est pas ouvert à tout le monde</p><p>Cette page suppose que vous ayez une fiche de personnel dans l&#39;établissement. Un compte sans fiche (un parent, un élève) n&#39;y a pas accès — voir <a href="/guide/admin/personnel-utilisateurs.html">Personnel et comptes utilisateurs</a> pour la création des fiches.</p></div><h2 id="statuer-sur-les-demandes-administration" tabindex="-1">Statuer sur les demandes (administration) <a class="header-anchor" href="#statuer-sur-les-demandes-administration" aria-label="Permalink to &quot;Statuer sur les demandes (administration)&quot;">​</a></h2><p>Un administrateur dispose d&#39;une vue supplémentaire, <strong>Demandes de congé</strong>, qui liste les demandes de <strong>tout</strong> le personnel.</p><p>Pour chaque demande :</p><ul><li><strong>Approuver</strong> l&#39;accorde immédiatement.</li><li><strong>Rejeter</strong> ouvre une fenêtre de confirmation demandant un <strong>motif du rejet</strong>. Ce motif est ensuite visible par la personne concernée dans son propre historique — c&#39;est ce qui lui évite de venir demander pourquoi.</li></ul><p>Une demande déjà traitée reste dans la liste avec sa décision : l&#39;historique sert de trace, rien n&#39;est effacé.</p>',16)])])}const g=t(r,[["render",o]]);export{m as __pageData,g as default};
